import React, { useState } from "react";
import api from "../api";

function MealPlan({ familyId }) {
    const [plan, setPlan] = useState(null);

    const generate = async () => {
        const res = await api.get(`/families/${familyId}/mealplan`);
        setPlan(res.data);
    };

    return (
        <div>
            <button onClick={generate}>Generate Meal Plan</button>

            {plan && (
                <div>
                    <p>Breakfast: {plan.breakfast}</p>
                    <p>Lunch: {plan.lunch}</p>
                    <p>Dinner: {plan.dinner}</p>
                </div>
            )}
        </div>
    );
}

export default MealPlan;
